WAYFINDER_KEYS = ["facts","assumptions","hypotheses","unknowns","blockers","decisions","investigations","risks"]

def yaml_list(values):
    if not values:
        return "[]"
    return "\n" + "\n".join(f"  - {x}" for x in values)

def skill_md(name, spec):
    req=yaml_list(spec["requires"]); outs=yaml_list(spec["outputs"])
    rules="\n".join(f"- {x}" for x in spec["rules"]); wf="\n".join(f"{i+1}. {x}" for i,x in enumerate(spec["workflow"])); bd="\n".join(f"- {x}" for x in spec["boundaries"])
    return f'''---\nname: {name}\ndescription: {spec["description"]}\nversion: 0.1.0\nstatus: candidate\nowners:\n  - GithubLarsKomo\nrequires: {req}\noutputs: {outs}\nlastEvaluated: {TODAY}\n---\n\n# {name}\n\n## Zweck\n\n{spec["purpose"]}\n\n## Trigger\n\n{spec["trigger"]}\n\n## Gemeinsame Regulated-Engineering-Regeln\n\n- Aussagen mit regulatorischer Wirkung trennen `regulation/law`, `standard`, `guidance`, `organizational-policy` und `interpretation`.\n- Zeitabhängige regulatorische Fakten benötigen `asOf` und eine nachvollziehbare Source-Referenz; fehlt sie, bleibt der Punkt `unknown`.\n- Volltexte urheberrechtlich geschützter Standards werden nicht reproduziert. Verwende zugängliche autoritative Quellen und organisationslizenzierte Normtexte nur als Evidenz.\n- Fehlende Evidenz ist kein positiver Compliance-Nachweis.\n- Bei High-Impact-Klassifikation, Zulassung, Zertifizierung, Freigabe oder Legal Interpretation wird die erforderliche menschliche/behördliche Autorität nicht simuliert.\n\n## Fachregeln\n\n{rules}\n\n## Workflow\n\n{wf}\n\n## Wayfinder-kompatible Übergabe\n\nWenn der nächste sichere Schritt durch Unsicherheit blockiert ist, gib eine begrenzte Übergabe mit diesen Feldern aus: `{', '.join(WAYFINDER_KEYS)}`. Investigations müssen eine einzelne Frage, benötigte Evidenz, Stop Condition und Nicht-Ziele enthalten.\n\n## Compliance Traceability\n\nVerknüpfe relevante Ergebnisse mit `compliance-traceability-v1` als `obligation -> product-requirement -> risk/rationale -> implementation/control -> verification -> evidence -> status`. Quellenbezogene regulatorische Claims folgen `regulatory-source-evidence-v1`.\n\n## Grenzen\n\n{bd}\n\n## Qualitätsgate\n\nPass nur, wenn Facts/Interpretations getrennt, Freshness sichtbar, zentrale Claims rückverfolgbar, Unknowns nicht positiv umgedeutet, Cross-Skill-Grenzen respektiert und die nächste Aktion ohne versteckte Regulatory-Annahme ausführbar ist.\n'''

def evaluation(name,spec):
    a=spec["anchors"]
    return {"schemaVersion":1,"skill":name,"cases":[
      {"id":"happy-path","input":f"Use {name} with complete current source evidence and a confirmed product context.","requiredBehaviors":["preserve regulatory source class and freshness","produce the declared domain outputs without duplicating orchestration","hand off only genuine critical uncertainty"],"forbiddenBehaviors":["invent authority approval or certification","convert missing evidence into compliance"],"skillAnchors":[a[0],"Zeitabhängige regulatorische Fakten benötigen `asOf`","Fehlende Evidenz ist kein positiver Compliance-Nachweis"]},
      {"id":"edge-case","input":f"Use {name} when one material source is stale, another contradicts it, and a key classification/decision remains unresolved.","requiredBehaviors":["keep stale/contradictory evidence visible","mark the decision unknown or hypothesis rather than final","produce a bounded Wayfinder-compatible investigation"],"forbiddenBehaviors":["use last-write-wins for regulatory evidence","hide an unresolved high-impact decision"],"skillAnchors":[a[1],"bleibt der Punkt `unknown`","Wayfinder-kompatible Übergabe"]},
      {"id":"failure-case","input":f"A draft using {name} applies fixed industry rules without sources and declares the product compliant/approved from a checklist.","requiredBehaviors":["reject unsourced universal rules","reject checklist-only compliance or approval","restore explicit source/evidence boundaries"],"forbiddenBehaviors":["simulate regulatory authority","invent universal thresholds or timelines"],"skillAnchors":[a[2],"menschliche/behördliche Autorität nicht simuliert","Compliance Traceability"]}]}

def result(name,case):
    return {"schemaVersion":1,"skill":name,"caseId":case["id"],"recordedAt":TODAY,"evaluator":"repository-maintainer","requiredBehaviors":[{"behavior":b,"passed":True,"evidence":"The skill contract explicitly requires this behavior and preserves uncertainty/evidence boundaries."} for b in case["requiredBehaviors"]],"forbiddenBehaviors":[{"behavior":b,"observed":False,"evidence":"The skill boundaries and quality gate explicitly reject this behavior."} for b in case["forbiddenBehaviors"]],"overall":"pass"}

def write(path,text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True)
    if isinstance(text,(dict,list)): text=json.dumps(text,ensure_ascii=False,indent=2,sort_keys=True)+"\n"
    p.write_text(text,encoding="utf-8")

for name,spec in SKILLS.items():
    write(f"skills/{name}/SKILL.md",skill_md(name,spec)); ev=evaluation(name,spec); write(f"skills/{name}/tests/evaluation.json",ev)
    for case in ev["cases"]: write(f"skills/{name}/tests/results/{case['id']}.json",json.dumps(result(name,case),ensure_ascii=False,sort_keys=True,separators=(",",":"))+"\n")

