write("tests/test_regulated_engineering_contracts.py", '''import json\nimport unittest\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parents[1]\nclass RegulatedEngineeringContractsTest(unittest.TestCase):\n def test_contract_schemas_parse_and_are_closed(self):\n  for name in ["regulatory-source-evidence-v1.schema.json","compliance-traceability-v1.schema.json","regulated-product-baseline-v1.schema.json"]:\n   value=json.loads((ROOT/"contracts"/name).read_text(encoding="utf-8")); self.assertEqual(value["$schema"],"https://json-schema.org/draft/2020-12/schema"); self.assertEqual(value["type"],"object"); self.assertFalse(value.get("additionalProperties",True)); self.assertTrue(value.get("required"))\n def test_source_contract_distinguishes_claim_class_and_freshness(self):\n  value=json.loads((ROOT/"contracts/regulatory-source-evidence-v1.schema.json").read_text()); self.assertIn("claimClass",value["required"]); self.assertIn("asOf",value["required"]); self.assertEqual(set(value["properties"]["claimClass"]["enum"]),{"regulation-law","standard","guidance","organizational-policy","interpretation"})\n def test_traceability_has_required_chain_node_types(self):\n  value=json.loads((ROOT/"contracts/compliance-traceability-v1.schema.json").read_text()); types=set(value["properties"]["nodes"]["items"]["properties"]["type"]["enum"]); self.assertTrue({"obligation","product-requirement","risk-rationale","implementation-control","verification","evidence","status"}.issubset(types))\nif __name__=="__main__": unittest.main()\n''')
write("tests/test_regulated_engineering_e2e.py", '''import json\nimport unittest\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parents[1]\nclass RegulatedEngineeringE2ETest(unittest.TestCase):\n @classmethod\n def setUpClass(cls):\n  cls.index=json.loads((ROOT/"docs/skill-capability-index.json").read_text(encoding="utf-8")); cls.skills={s["name"]:s for s in cls.index["skills"]}\n def test_all_e2e_sequences_resolve(self):\n  bench=json.loads((ROOT/"benchmarks/regulated-engineering-e2e-v1.json").read_text())\n  for scenario in bench["scenarios"]:\n   for name in scenario["sequence"]: self.assertIn(name,self.skills,f"{scenario['id']}: {name}")\n   self.assertTrue(scenario["mustPreserve"])\n def test_routing_benchmark_targets_exist_and_are_specific(self):\n  bench=json.loads((ROOT/"benchmarks/regulated-engineering-routing-v1.json").read_text())\n  for case in bench["cases"]:\n   target=self.skills[case["expectedSkill"]]; self.assertTrue(target.get("description"))\n   for companion in case.get("companionSkills",[]): self.assertIn(companion,self.skills)\n   for other in case.get("notPrimary",[]): self.assertIn(other,self.skills)\n def test_regulatory_strategy_is_thin_orchestrator(self):\n  req=set(self.skills["medical-device-regulatory-strategy"]["requires"]); self.assertTrue({"eu-mdr-ivdr-regulatory-specialist","fda-medical-device-ivd-regulatory-specialist","large-work-wayfinder"}.issubset(req))\n def test_audits_share_compliance_review_core(self):\n  for name in ["iso13485-qms-audit","iso27001-isms-audit"]: self.assertIn("two-axis-compliance-review",self.skills[name]["requires"])\nif __name__=="__main__": unittest.main()\n''')

